        'important_terms' => [
            ['term' => 'Body Mass Index (BMI)', 'definition' => 'A clinical measure of body fat based on height and weight (kg/m2) used in DSM-5 to standardize severity grading in Anorexia Nervosa.'],
            ['term' => 'Extreme Anorexia', 'definition' => 'Anorexia Nervosa characterized by a BMI below 15 kg/m2, presenting imminent medical risk of cardiac arrest and requiring urgent hospitalization.'],
            ['term' => 'Lanugo', 'definition' => 'Fine, soft, downy body hair that develops on the face, back, and arms of severely starved anorexic patients as a physiological thermoregulatory response.'],
            ['term' => 'Body Checking', 'definition' => 'Compulsive behavioral rituals in eating disorders involving pinching skin folds, measuring wrists, or constant weighing to verify thinness.']
